+        /// <summary>
+        /// 严选电商自动可清单
+        /// </summary>
+        /// <param name="orderIds"></param>
+        /// <returns></returns>
+        public async Task AutoPlugin(IEnumerable<int> orderIds)
+        {
+            try
+            {
+                foreach (var orderId in orderIds)
+                {
+                    var ordr = await UnitWork.FindSingleAsync<ORDR>(x => x.DocEntry == orderId);
+                    var ordrStat = await UnitWork.FindSingleAsync<OrdrStat>(x => x.Code == orderId.ToString());
+
+                    if (ordrStat.U_ReceivePayStatus != 1)
+                    {
+                        continue;
+                    }
+
+                    var docTotalRMB = ordr.DocTotal.Value;
+                    if (docTotalRMB <= 0)
+                        continue;
+
+                    var balanceRMB = CalculateBalanceRMB(ordr, ordrStat);
+                    var paymentRate = CalculatePaymentRate(ordr, ordrStat, balanceRMB);
+                    if (paymentRate == null)
+                        continue;
+
+                    bool shouldPlugin = ShouldAutoPlugin(ordrStat, paymentRate.Value, balanceRMB);
+                    if (!shouldPlugin) continue;
+
+                    LogHelper.Info(string.Format("自动可清单：销售单号：{0}；订单金额(人民币){1}；余额(人民币){2}；回款率{3}%",
+                        orderId, docTotalRMB, balanceRMB, paymentRate * 100), nameof(FinanceHanlerApp), nameof(AutoPlugin));
+
+                    await ProcessOrderPluginAsync(orderId);
+                }
+            }
+            catch (Exception e)
+            {
+                LogHelper.Error(e, "订单自动可清单执行失败", nameof(FinanceHanlerApp), nameof(AutoPlugin));
+            }
+        }
+
+        /// <summary>
+        /// 计算人民币余额
+        /// </summary>
+        private decimal CalculateBalanceRMB(ORDR ordr, OrdrStat ordrStat)
+        {
+            var receiptAmountRMB = ordr.U_DocRCTAmount ?? 0M;
+            var uRefundAmtRMB = ordrStat.U_Refund_Amt;
+
+            if (ordr.DocStatus == "C")
+            {
+                return (ordrStat.U_Delivery_TotalAmt ?? 0) - (receiptAmountRMB - uRefundAmtRMB);
+            }
+            else
+            {
+                return ordr.DocTotal.Value - (receiptAmountRMB - uRefundAmtRMB);
+            }
+        }
+
+        /// <summary>
+        /// 计算回款率
+        /// </summary>
+        private decimal? CalculatePaymentRate(ORDR ordr, OrdrStat ordrStat, decimal balanceRMB)
+        {
+            var receiptAmountRMB = ordr.U_DocRCTAmount ?? 0M;
+            var uRefundAmtRMB = ordrStat.U_Refund_Amt;
+
+            if (ordr.DocCur == FinanceConsts.RMB)
+            {
+                if (balanceRMB <= 0)
+                {
+                    return null;
+                }
+                return (receiptAmountRMB - uRefundAmtRMB) / ordr.DocTotal.Value;
+            }
+            else
+            {
+                var docTotalFC = ordr.DocTotalFC.Value;
+                var receiptAmountFC = ordrStat.U_Receipt_TotalAmtFC ?? 0M;
+                var uRefundAmtFC = ordrStat.U_Refund_AmtFC;
+
+                if (docTotalFC <= 0)
+                    return null;
+                if (docTotalFC - (receiptAmountFC - uRefundAmtFC) <= 0)
+                    return null;
+
+                return (receiptAmountFC - uRefundAmtFC) / docTotalFC;
+            }
+        }
+
+        /// <summary>
+        /// 判断是否应该自动可清单
+        /// </summary>
+        private bool ShouldAutoPlugin(OrdrStat ordrStat, decimal paymentRate, decimal balanceRMB)
+        {
+            return ordrStat.U_ReceivePayStatus == 1 ||
+                   (paymentRate >= 0.98m && Math.Abs(balanceRMB) < 100m);
+        }
